CREATE SCHEMA IF NOT EXISTS esquema_autenticacion;
CREATE TABLE IF NOT EXISTS esquema_autenticacion.roles(id_rol BIGSERIAL PRIMARY KEY,nombre VARCHAR(40) NOT NULL UNIQUE,descripcion VARCHAR(200),activo BOOLEAN NOT NULL DEFAULT TRUE,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS esquema_autenticacion.permisos(id_permiso BIGSERIAL PRIMARY KEY,clave_permiso VARCHAR(80) NOT NULL UNIQUE,descripcion VARCHAR(200));
CREATE TABLE IF NOT EXISTS esquema_autenticacion.permisos_roles(id_rol BIGINT NOT NULL REFERENCES esquema_autenticacion.roles(id_rol) ON DELETE CASCADE,id_permiso BIGINT NOT NULL REFERENCES esquema_autenticacion.permisos(id_permiso) ON DELETE CASCADE,PRIMARY KEY(id_rol,id_permiso));
CREATE TABLE IF NOT EXISTS esquema_autenticacion.usuarios(id_usuario BIGSERIAL PRIMARY KEY,id_rol BIGINT NOT NULL REFERENCES esquema_autenticacion.roles(id_rol),codigo_trabajador VARCHAR(30) NOT NULL UNIQUE,nombre_completo VARCHAR(120) NOT NULL,correo VARCHAR(160),hash_clave VARCHAR(100) NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW(),fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS ux_usuarios_correo_minuscula ON esquema_autenticacion.usuarios(LOWER(correo)) WHERE correo IS NOT NULL;
CREATE TABLE IF NOT EXISTS esquema_autenticacion.eventos_autenticacion(id_evento_autenticacion BIGSERIAL PRIMARY KEY,id_usuario BIGINT REFERENCES esquema_autenticacion.usuarios(id_usuario) ON DELETE SET NULL,codigo_trabajador_intentado VARCHAR(30),tipo_evento VARCHAR(30) NOT NULL CHECK(tipo_evento IN('INICIO_SESION_CORRECTO','INICIO_SESION_FALLIDO','CIERRE_SESION','TOKEN_REVOCADO')),direccion_ip INET,agente_usuario TEXT,detalles JSONB NOT NULL DEFAULT '{}'::JSONB,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO esquema_autenticacion.roles(nombre,descripcion) VALUES('ADMINISTRADOR','Acceso general'),('MOZO','Toma de comandas'),('CAJERO','Caja'),('COCINERO','Cocina'),('ALMACENERO','Inventario') ON CONFLICT(nombre) DO NOTHING;
INSERT INTO esquema_autenticacion.permisos(clave_permiso,descripcion) VALUES('usuarios.administrar','Administrar usuarios'),('mesas.consultar','Consultar mesas'),('menu.consultar','Consultar menú'),('pedidos.crear','Crear comandas'),('pedidos.consultar','Consultar comandas'),('pedidos.trasladar','Trasladar comandas'),('cocina.consultar','Ver cocina'),('caja.cobrar','Cobrar'),('inventario.administrar','Gestionar inventario') ON CONFLICT(clave_permiso) DO NOTHING;
INSERT INTO esquema_autenticacion.permisos_roles(id_rol,id_permiso) SELECT r.id_rol,p.id_permiso FROM esquema_autenticacion.roles r CROSS JOIN esquema_autenticacion.permisos p WHERE r.nombre='ADMINISTRADOR' ON CONFLICT DO NOTHING;
INSERT INTO esquema_autenticacion.permisos_roles(id_rol,id_permiso) SELECT r.id_rol,p.id_permiso FROM esquema_autenticacion.roles r JOIN esquema_autenticacion.permisos p ON p.clave_permiso IN('mesas.consultar','menu.consultar','pedidos.crear','pedidos.consultar','pedidos.trasladar') WHERE r.nombre='MOZO' ON CONFLICT DO NOTHING;
INSERT INTO esquema_autenticacion.permisos_roles(id_rol,id_permiso) SELECT r.id_rol,p.id_permiso FROM esquema_autenticacion.roles r JOIN esquema_autenticacion.permisos p ON p.clave_permiso IN('menu.consultar','cocina.consultar') WHERE r.nombre='COCINERO' ON CONFLICT DO NOTHING;
